        System.out.println(account);
    }
}

sealed interface Shape permits Circle, Rectangle {}
record Circle(double radius) implements Shape {}
record Rectangle(double width, double height) implements Shape {}

public class ShapeAreas {
    static double area(Shape shape) {
        return switch (shape) {
            case Circle(double r) -> Math.PI * r * r;
            case Rectangle(double w, double h) -> w * h;
        };
    }

    public static void main(String[] args) {
        Shape[] shapes = { new Circle(1.5), new Rectangle(2, 3.5) };
        for (Shape shape : shapes) {
            System.out.printf("%s -> %.2f%n", shape, area(shape));
        }
    }
}

import java.util.Map;
import java.util.TreeMap;

public class WordFrequency {
    public static void main(String[] args) {
        String text = "the quick brown fox jumps over the lazy dog the end";
        Map<String, Integer> counts = new TreeMap<>();
        for (String word : text.split(" ")) {
            counts.merge(word, 1, Integer::sum);
        }
        counts.forEach((word, count) -> {
            if (count > 1) {
                System.out.println(word + ": " + count);
            }
        });
        System.out.println(counts.size() + " distinct words");
    }
}

import java.util.Arrays;
import java.util.IntSummaryStatistics;

public class GradeStatistics {
    public static void main(String[] args) {
        int[] grades = {88, 72, 95, 60, 79};
        IntSummaryStatistics stats = Arrays.stream(grades).summaryStatistics();
        System.out.println("min " + stats.getMin() + ", max " + stats.getMax());
        System.out.printf("average %.1f%n", stats.getAverage());
        long passed = Arrays.stream(grades).filter(g -> g >= 70).count();
        System.out.println(passed + " of " + grades.length + " passed");
    }
}

