import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.stream.Stream;

public class LineCount {
    public static void main(String[] args) throws IOException {
        Path file = Path.of("poem.txt");
        Files.writeString(file, "Roses are red\nViolets are blue\n\nJava is typed\nAnd so are you\n");
        try (Stream<String> lines = Files.lines(file)) {
            long nonEmpty = lines.filter(line -> !line.isBlank()).count();
            System.out.println(nonEmpty + " non-empty lines");
        }
        System.out.println(Files.readAllLines(file).size() + " lines in total");
        System.out.println(Files.size(file) + " bytes");
    }
}

public class Palindrome {
    static boolean isPalindrome(String text) {
        String letters = text.toLowerCase().replaceAll("[^a-z0-9]", "");
        String reversed = new StringBuilder(letters).reverse().toString();
        return letters.equals(reversed);
    }

    public static void main(String[] args) {
        String[] samples = {"racecar", "A man, a plan, a canal: Panama", "Java"};
        for (String sample : samples) {
            System.out.println(sample + " -> " + isPalindrome(sample));
        }
    }
}

enum Light {
    RED(30), GREEN(25), YELLOW(5);

    private final int seconds;

    Light(int seconds) {
        this.seconds = seconds;
    }

    Light next() {
        return switch (this) {
            case RED -> GREEN;
            case GREEN -> YELLOW;
            case YELLOW -> RED;
        };
    }

    int seconds() {
        return seconds;
    }
}

public class TrafficLight {
    public static void main(String[] args) {
        Light light = Light.RED;
        for (int i = 0; i < 4; i++) {
            System.out.println(light + " for " + light.seconds() + "s");
            light = light.next();
        }
    }
}

import java.util.List;

public class SafeParse {
    static int parseOrDefault(String text, int fallback) {
        try {
            return Integer.parseInt(text.strip());
        } catch (NumberFormatException e) {
            System.out.println("Ignoring '" + text + "': " + e.getMessage());
            return fallback;
        }
    }

    public static void main(String[] args) {
        List<String> inputs = List.of("12", " 7 ", "x3", "", "40");
        int sum = 0;
        for (String input : inputs) {
            sum += parseOrDefault(input, 0);
        }
        System.out.println("Sum: " + sum);
    }
}

public class Pair<A, B> {
    private final A first;
    private final B second;

    public Pair(A first, B second) {
        this.first = first;
        this.second = second;
    }

    public A first() {
        return first;
    }

    public B second() {
        return second;
    }

    public Pair<B, A> swap() {
        return new Pair<>(second, first);
    }

    @Override
    public String toString() {
        return "(" + first + ", " + second + ")";
    }

    public static void main(String[] args) {
        Pair<String, Integer> entry = new Pair<>("age", 36);
        Pair<Integer, String> swapped = entry.swap();
        System.out.println(entry);
        System.out.println(swapped);
        int next = swapped.first() + 1;
        System.out.println(next);
    }
}
